import {createHash} from 'node:crypto';
export const DOCUMENT_TYPES=['boat','car','property','parking','pool'];
export function scope(type:string,id:string){if(!DOCUMENT_TYPES.includes(type)||!/^[a-zA-Z0-9_-]{1,160}$/.test(id))throw Object.assign(Error('invalid_asset'),{status:400});}
export function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function validDate(s:any){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;}
export function fileKind(b:Buffer){if(b.subarray(0,5).toString()==='%PDF-')return {ext:'pdf',mime:'application/pdf'};if(b[0]===255&&b[1]===216&&b[2]===255)return {ext:'jpg',mime:'image/jpeg'};if(b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))return {ext:'png',mime:'image/png'};return null;}
export function legacyDocumentName(owner:string,type:string,id:string,doc:string,ext:string){scope(type,id);if(!/^[a-f0-9-]{36}$/.test(doc)||!['pdf','jpg','png'].includes(ext))throw Error('invalid_document_path');return `private/asset-documents/${createHash('sha256').update(owner).digest('hex')}/${type}/${id}/${doc}.${ext}`;}
export const DOCUMENT_BUCKET='ailla-poc.appspot.com';
export const DOCUMENT_FOLDERS:Record<string,string>={boat:'boats',car:'cars',property:'lodging',parking:'parkings',pool:'pools'};
export function objectName(_owner:string,type:string,id:string,doc:string,ext:string){scope(type,id);if(!/^[a-f0-9-]{36}$/.test(doc)||!['pdf','jpg','png'].includes(ext))throw Error('invalid_document_path');return `assets/${DOCUMENT_FOLDERS[type]}/${id}/documents/${doc}.${ext}`;}
export function catalogOK(c:any,type:string){return c?.version&&Array.isArray(c?.types?.[type])&&c.types[type].length>0&&c.types[type].every((r:any)=>/^[a-zA-Z0-9_-]+$/.test(r.id)&&['required','conditional','recommended'].includes(r.policy)&&typeof r.expiryRequired==='boolean');}
export function checklist(c:any,type:string,owner:string,dossier:any,date=today()){
 if(!catalogOK(c,type))throw Object.assign(Error('document_policy_missing'),{status:503});
 return c.types[type].map((r:any)=>{const files=Object.values<any>(dossier?.files||{}).filter(d=>d.ownerId===owner&&d.requirementId===r.id&&(d.status!=='removed'||d.purgePending===true));const valid=(d:any)=>d.policyVersion===c.version&&(!d.expiresOn||d.expiresOn>=date)&&(!r.expiryRequired||validDate(d.expiresOn));const w=dossier?.waivers?.[r.id];const waived=r.policy==='conditional'&&w?.ownerId===owner&&w.status==='approved'&&w.policyVersion===c.version&&(!w.expiresOn||w.expiresOn>=date);const approved=files.some(d=>d.status==='approved'&&valid(d));return {...r,files,waiver:w?.ownerId===owner?w:null,status:approved?'approved':waived?'waived':files.some(d=>d.status==='approved')?'expired':files.some(d=>d.status==='pending')?'pending':files.length?'rejected':'missing',complete:approved||waived||r.policy==='recommended'};});
}
export function documentFingerprint(d:any){const files=Object.values<any>(d?.files||{}).filter(f=>f.status!=='removed').map(f=>[f.id,f.ownerId,f.requirementId,f.revision,f.status,f.expiresOn||'',f.policyVersion,f.sha256||'']).sort((a,b)=>String(a[0]).localeCompare(String(b[0])));const waivers=Object.entries<any>(d?.waivers||{}).map(([id,w])=>[id,w.ownerId,w.revision,w.status,w.expiresOn||'',w.policyVersion,w.reason||'']).sort((a,b)=>String(a[0]).localeCompare(String(b[0])));return createHash('sha256').update(JSON.stringify({files,waivers,adminExemption:d?.adminExemption||null})).digest('hex');}
export function documentSummary(c:any,type:string,owner:string,d:any){try{const rows=checklist(c,type,owner,d),complete=rows.every((r:any)=>r.complete),review=d?.review?.ownerId===owner?d.review:null,fingerprint=documentFingerprint(d);const readProof=rows.every((r:any)=>r.files.every((f:any)=>f.status!=='approved'||(f.reviewConfirmed===true&&!!d?.reads?.[f.id]?.[f.reviewedBy]?.[f.revision-1])));const exemption=d?.adminExemption;const exempted=exemption?.active===true&&exemption.ownerId===owner&&exemption.policyVersion===c.version&&typeof exemption.reason==='string'&&exemption.reason.trim().length>=10&&typeof exemption.grantedBy==='string'&&(!exemption.expiresOn||exemption.expiresOn>=today());const approved=exempted||(complete&&readProof&&review?.status==='approved'&&review.policyVersion===c.version&&review.fingerprint===fingerprint);const provided=rows.every((r:any)=>r.policy==='recommended'||r.files.some((f:any)=>['pending','approved'].includes(f.status)&&(!r.expiryRequired||validDate(f.expiresOn))&&(!f.expiresOn||f.expiresOn>=today()))||(r.policy==='conditional'&&r.waiver&&['pending','approved'].includes(r.waiver.status)&&(!r.waiver.expiresOn||r.waiver.expiresOn>=today())));return{approved,complete,provided,fingerprint,exempted,adminExemption:exemption?.ownerId===owner?exemption:null,status:exempted?'exempted':approved?'validated':rows.some((r:any)=>r.status==='expired')?'expiredDossier':review?.status==='rejected'?'refused':review?.submittedAt?'pendingReview':'draft',reason:review?.reason||'',submittedAt:review?.submittedAt||null,total:rows.filter((r:any)=>r.policy!=='recommended').length,validated:rows.filter((r:any)=>r.policy!=='recommended'&&r.complete).length,pendingWaivers:rows.filter((r:any)=>r.waiver?.status==='pending').length,pendingFiles:rows.reduce((n:number,r:any)=>n+r.files.filter((f:any)=>f.status==='pending').length,0)};}catch{return{approved:false,complete:false,provided:false,fingerprint:documentFingerprint(d),status:'incomplete',reason:'',submittedAt:null,total:0,validated:0,pendingFiles:0};}}
export async function assetDocumentStatus(store:any,type:string,id:string,owner:string){const [c,d]=await Promise.all([store.db.ref('publicContent/documentRequirements').once('value'),store.db.ref(`assetDocuments/${type}/${id}`).once('value')]);return documentSummary(c.val(),type,owner,d.val());}
export async function documentsPermitPublication(store:any,type:string,id:string,owner:string){return (await assetDocumentStatus(store,type,id,owner)).approved;}
